module query_processor (\n    input clk,\n    input rst_n,\n    input start,\n    input [1:0] query_type,\n    input [3:0] update_pos,\n    input [2:0] update_value,\n    output reg [15:0] result,\n    output reg done\n);\n\n    // Array storage for 16 elements (3-bit each)\n    reg [2:0] array_reg [0:15];\n\n    // FSM states\n    localparam [3:0]\n        IDLE           = 4'd0,\n        UPDATE_PROCESS = 4'd1,\n        GET_MAX        = 4'd2,\n        GET_MAX_LOOP   = 4'd3,\n        COMP_K         = 4'd4,\n        INIT_LEFT      = 4'd5,\n        LEFT_LOOP      = 4'd6,\n        INIT_WINDOW    = 4'd7,\n        RIGHT_LOOP     = 4'd8,\n        PROCESS_ELEM   = 4'd9,\n        CHECK_COVERED  = 4'd10,\n        UPDATE_MIN     = 4'd11,\n        NEXT_LEFT      = 4'd12,\n        FINISH_QUERY   = 4'd13;\n\n    reg [3:0] current_state, next_state;\n\n    // Processing variables\n    reg [3:0]  index;    // For max search\n    reg [2:0]  max_temp; // Max stored value\n    reg [3:0]  K;        // max_temp + 1\n    reg [3:0]  i, j;     // Loop indices\n    reg [4:0]  found_flags; // Presence flags [1..5]\n    reg [4:0]  min_len;  // 5-bit width (0-16)\n\n    wire [4:0] mask;     // Coverage mask\n\n    // Coverage mask generator\n    assign mask = (K == 4'd1) ? 5'b00001 :\n                  (K == 4'd2) ? 5'b00011 :\n                  (K == 4'd3) ? 5'b00111 :\n                  (K == 4'd4) ? 5'b01111 :\n                  5'b11111;\n\n    integer k; // For reset loop\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            current_state <= IDLE;\n            done <= 1'b0;\n            result <= 16'd0;\n            // Initialize array\n            for (k = 0; k < 16; k = k + 1) begin\n                array_reg[k] <= 3'd0;\n            end\n            max_temp <= 3'd0;\n            K <= 4'd0;\n            i <= 4'd0;\n            j <= 4'd0;\n            found_flags <= 5'd0;\n            min_len <= 5'd17;\n        end else begin\n            current_state <= next_state;\n\n            case (current_state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        if (query_type == 2'b01) begin\n                            next_state <= UPDATE_PROCESS;\n                        end else if (query_type == 2'b10) begin\n                            next_state <= GET_MAX;\n                            max_temp <= 3'd0;\n                            index <= 4'd0;\n                        end\n                    end else begin\n                        next_state <= IDLE;\n                    end\n                end\n\n                UPDATE_PROCESS: begin\n                    array_reg[update_pos - 4'd1] <= update_value;\n                    done <= 1'b1;\n                    next_state <= IDLE;\n                end\n\n                GET_MAX: begin\n                    index <= 4'd0;\n                    max_temp <= 3'd0;\n                    next_state <= GET_MAX_LOOP;\n                end\n\n                GET_MAX_LOOP: begin\n                    if (array_reg[index] > max_temp) begin\n                        max_temp <= array_reg[index];\n                    end\n\n                    if (index == 4'd15) begin\n                        next_state <= COMP_K;\n                    end else begin\n                        index <= index + 4'd1;\n                        next_state <= GET_MAX_LOOP;\n                    end\n                end\n\n                COMP_K: begin\n                    K <= max_temp + 4'd1;\n                    next_state <= INIT_LEFT;\n                end\n\n                INIT_LEFT: begin\n                    i <= 4'd0;\n                    min_len <= 5'd17;\n                    next_state <= LEFT_LOOP;\n                end\n\n                LEFT_LOOP: begin\n                    if (i >= 4'd16) begin\n                        next_state <= FINISH_QUERY;\n                    end else begin\n                        next_state <= INIT_WINDOW;\n                    end\n                end\n\n                INIT_WINDOW: begin\n                    j <= i;\n                    found_flags <= 5'd0;\n                    next_state <= RIGHT_LOOP;\n                end\n\n                RIGHT_LOOP: begin\n                    if (j >= 4'd16) begin\n                        next_state <= NEXT_LEFT;\n                    end else begin\n                        next_state <= PROCESS_ELEM;\n                    end\n                end\n\n                PROCESS_ELEM: begin\n                    found_flags[array_reg[j]] <= 1'b1;\n                    next_state <= CHECK_COVERED;\n                end\n\n                CHECK_COVERED: begin\n                    if ((found_flags & mask) == mask) begin\n                        if ((j - i + 1) < min_len) begin\n                            min_len <= j - i + 1;\n                        end\n                        next_state <= NEXT_LEFT;\n                    end else begin\n                        j <= j + 4'd1;\n                        next_state <= RIGHT_LOOP;\n                    end\n                end\n\n                NEXT_LEFT: begin\n                    i <= i + 4'd1;\n                    next_state <= LEFT_LOOP;\n                end\n\n                FINISH_QUERY: begin\n                    if (min_len == 5'd17) begin\n                        result <= 16'hFFFF; // -1\n                    end else begin\n                        result <= {{11{1'b0}}, min_len};\n                    end\n                    done <= 1'b1;\n                    next_state <= IDLE;\n                end\n\n                default: next_state <= IDLE;\n            endcase\n        end\n    end\nendmodule